var CONTACT_EMAIL='';  /* 由 data/config.json → contactEmail 注入；留空则回退到 repoUrl/issues */
function moodFaceSVG(c,s){s=s||15;return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 24 24" fill="none" stroke="'+c+'" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><circle cx="9" cy="10" r="1.1" fill="'+c+'" stroke="none"/><circle cx="15" cy="10" r="1.1" fill="'+c+'" stroke="none"/><path d="M8 15c1.5 2 6.5 2 8 0"/></svg>'}
function $(s){return document.querySelector(s)}
function $$(s){return document.querySelectorAll(s)}
function rand(a,b){return Math.floor(Math.random()*(b-a+1))+a}
function randItem(a){return a[Math.floor(Math.random()*a.length)]}
function formatMoney(n){return (typeof n==='number'&&isFinite(n)?n:0).toLocaleString('zh-CN')}
function pad(n){return n<10?'0'+n:''+n}
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
/* 玩家自由输入的名字：会被拼进 innerHTML 也会进存档，去掉标记字符并限长，别撑坏界面 */
function cleanName(s,max){
  s=String(s==null?'':s).replace(/[<>"'&`]/g,'').trim();
  var m=max||12;
  return s.length>m?s.slice(0,m):s;
}
/* 营业时间：一天 0:00-24:00，午夜切换新一天（1段=1小时）；深夜打烊客流稀 */
/* 数据已外置 → data/ 下 JSON，由 ensureDataLoaded() 注入 */
function dineline(dayTimer){
  var t=(dayTimer||0)%DAY_LENGTH;
  var seg=DAY_LENGTH/24;
  var idx=Math.min(23,Math.floor(t/seg));
  var frac=Math.max(0,Math.min(1,(t-idx*seg)/seg));
  var h0=parseInt(DINE_HOURS[idx][0],10);
  var h=h0+frac;
  var mm=Math.floor(h%1*60),hh=Math.floor(h)%24;
  var ampm=hh>=12?'下午':'上午';
  var h12=hh%12===0?12:hh%12;
  return {hour:hh,min:mm,label:ampm+h12+':'+pad(mm),idx:idx};
}
function dineMood(dayTimer){
  var idx=dineline(dayTimer).idx;
  if(idx<7)return'night';
  if(idx<9)return'dawn';
  if(idx<11)return'morning';
  if(idx<14)return'lunch';
  if(idx<17)return'day';
  if(idx<21)return'dinner';
  return'night';
}
/* v42 消息提示收口：同文案合并成 ×N、屏幕最多两行、多出来的进短队列。
   原来连弹三条能压到 100px 高，把顶部资金状态栏整个糊住。 */
var TOAST_MAX=2,TOAST_HOLD=2200,TOAST_RUSH=1200,TOAST_FADE=200,TOAST_QMAX=4,TOAST_QTTL=5000;
var _toastLive=[],_toastPend=[];
function _toastTop(){
  var c=$('#toast-container');if(!c)return null;
  var top=28;/* 固定挂在 28px 状态栏下沿；爆单倒计时在状态栏内，不占额外高度 */
  if(c.getAttribute('data-top')!==String(top)){c.setAttribute('data-top',String(top));c.style.top=top+'px'}
  return c;
}
function _toastHold(live,rush){
  clearTimeout(live.tm);clearTimeout(live.to);live.rush=!!rush;
  live.tm=setTimeout(function(){
    live.el.classList.add('out');
    live.to=setTimeout(function(){_toastDrop(live)},TOAST_FADE);
  },rush?TOAST_RUSH:TOAST_HOLD);
}
function _toastShow(item,rush){
  var c=$('#toast-container');if(!c)return;
  var e=document.createElement('div');
  e.className='toast'+(item.t?' '+item.t:'');
  e.innerHTML='<span class="t-msg">'+item.m+'</span><span class="t-n"></span>';
  c.appendChild(e);
  var live={key:item.key,el:e,n:1,rush:false,tm:0,to:0};
  _toastLive.push(live);_toastHold(live,rush);
}
function _toastDrop(live){
  var i=_toastLive.indexOf(live);if(i>=0)_toastLive.splice(i,1);
  if(live.el.parentNode)live.el.remove();
  _toastPump();
}
/* toast 文案里常夹着 icon 的 SVG，转进通知中心时只留纯文字 */
function _toastPlain(m){
  var d=document.createElement('div');
  d.innerHTML=String(m==null?'':m);
  return (d.textContent||'').replace(/\s+/g,' ').trim();
}
function _toastPump(){
  if(!_toastTop())return;
  var now=Date.now();
  while(_toastPend.length&&_toastLive.length<TOAST_MAX){
    var p=_toastPend.shift();
    if(now-p.at>TOAST_QTTL)continue;/* 洪峰过去后别再补一屏旧消息 */
    _toastShow(p,_toastPend.length>0);
  }
}
function showToast(m,t){
  /* 小游戏在屏时不弹主经营的提示：后台 tick 里的成交/爆单/事件
     统一折进通知中心的「后台经营动态」，别糊在 PK / 狼人杀画面上 */
  if(typeof G!=='undefined'&&G._bgTick){G.addBgToast(m);return}
  var c=_toastTop();if(!c)return;
  /* 容器被外部清空过（切页、巡检脚本）就先丢掉失效记录，把位置立刻腾出来 */
  for(var i=_toastLive.length-1;i>=0;i--){var dead=_toastLive[i];if(!dead.el.parentNode){clearTimeout(dead.tm);clearTimeout(dead.to);_toastLive.splice(i,1)}}
  var key=(t||'')+'\u0001'+m;
  for(var j=0;j<_toastLive.length;j++){
    var live=_toastLive[j];
    if(live.key!==key)continue;
    live.n++;live.el.lastChild.textContent=live.n>1?'×'+live.n:'';
    live.el.classList.add('bump');setTimeout(function(el){return function(){el.classList.remove('bump')}}(live.el),240);
    _toastHold(live,_toastPend.length>0);
    return;
  }
  if(_toastLive.length>=TOAST_MAX){
    /* 两行满了：新消息排队，同时把在场的两条切成"快进快出"，不然洪峰会堵死 */
    for(var k=0;k<_toastLive.length;k++)if(!_toastLive[k].rush)_toastHold(_toastLive[k],true);
    _toastPend.push({key:key,m:m,t:t||'',at:Date.now()});
    while(_toastPend.length>TOAST_QMAX)_toastPend.shift();
    return;
  }
  _toastShow({key:key,m:m,t:t||''},_toastPend.length>0);
}
var DAY_LENGTH=288;/* 现实秒数=游戏1天（4分48秒，每时段整12秒） */
/* v18: 营业时长选择 */
/* 数据已外置 → data/ 下 JSON，由 ensureDataLoaded() 注入 */
function getVirtualDate(day){
  var y=new Date().getFullYear();
  return new Date(y,0,(day||1));
}
function formatVirtualDate(day){
  var d=getVirtualDate(day);
  var wk=['周日','周一','周二','周三','周四','周五','周六'][d.getDay()];
  return d.getFullYear()+'年'+(d.getMonth()+1)+'月'+d.getDate()+'日 '+wk;
}
function getSeason(day){
  var m=getVirtualDate(day).getMonth()+1;
  if(m===1||m===2)return 'winter';
  if(m>=6&&m<=8)return 'summer';
  return 'normal';
}
function getSeasonLabel(day){
  var s=getSeason(day);
  return s==='winter'?'寒假季':s==='summer'?'暑假季':'常规季';
}
/* 窄屏（手机）下状态栏只显示「第N天 · 几点」，隐藏日期与营业状态 */
function isNarrowSB(){return typeof window!=='undefined'&&window.innerWidth<768;}
function updateSB(){
  var dayEl=$('#sb-day-text');
  var clockEl=$('#sb-clock-text');
  if(!dayEl||!clockEl)return;
  var day=G&&G.state?G.state.day:1;
  dayEl.textContent='第'+day+'天';
  var dateStr=formatVirtualDate(day);
  var dn=G&&G.state?dineline(G.state.dayTimer):{label:'上午9:00'};
  var clockStr=dn.label;
  if(!isNarrowSB())clockStr=dateStr+' '+dn.label;
  if(G&&G.state&&!isNarrowSB()){
    var mood=dineMood(G.state.dayTimer);
    var _curH=Math.floor((G.state.dayTimer||0)/12);
    var _isOpen=_curH>=(G.state.bizOpenHour||0)&&_curH<(G.state.bizCloseHour||24);
    var _vd2=getVirtualDate(G.state.day);var _dow2=_vd2.getDay();
    if(G.state.bizDays&&G.state.bizDays.indexOf(_dow2)<0)_isOpen=false;
    var label=_isOpen?(mood==='night'?'·深夜':(mood==='dawn'?'·早餐':(mood==='morning'?'·营业':(mood==='lunch'?'·午餐高峰':(mood==='day'?'·下午':(mood==='dinner'?'·晚餐高峰':'·营业中')))))):'·打烊';
    clockStr+=label;
  }
  clockEl.textContent=clockStr;
  /* also update day-row if visible */
  var dc=$('#day-clock');
  if(dc&&G&&G.state){
    var dn2=dineline(G.state.dayTimer);
    var mood2=dineMood(G.state.dayTimer);
    var _curH2=Math.floor((G.state.dayTimer||0)/12);
    var _isOpen2=_curH2>=(G.state.bizOpenHour||0)&&_curH2<(G.state.bizCloseHour||24);
    var _vd3=getVirtualDate(G.state.day);var _dow3=_vd3.getDay();
    if(G.state.bizDays&&G.state.bizDays.indexOf(_dow3)<0)_isOpen2=false;
    var label2=_isOpen2?(mood2==='night'?'·深夜打烊':(mood2==='dawn'?'·清晨早餐':(mood2==='morning'?'·上午营业':(mood2==='lunch'?'·午餐高峰':(mood2==='day'?'·下午营业':(mood2==='dinner'?'·晚餐高峰':'·营业中')))))):'·打烊中';
    dc.textContent=dn2.label+label2;
  }
}
var CAL={y:0,m:0},calTimer=null;
function calToday(){
  var vd=getVirtualDate(G&&G.state?G.state.day:1);
  CAL.y=vd.getFullYear();CAL.m=vd.getMonth();
}
function renderCalClock(){
  var c=$('#cal-clock');if(!c)return;
  var frac=(G&&G.state)?(G.state.dayTimer||0)/DAY_LENGTH:0;
  if(frac<0)frac=0;if(frac>1)frac=1;
  var dayH=frac*24;
  var hh=Math.floor(dayH)%24,mm=Math.floor(dayH%1*60),ss=Math.floor((dayH*3600)%60);
  c.innerHTML=pad(hh)+'<span class="colon">:</span>'+pad(mm)+'<span class="colon">:</span>'+pad(ss);
  var d=$('#cal-date');
  if(d)d.innerHTML='游戏日 '+formatVirtualDate(G&&G.state?G.state.day:1);
}
function renderCal(){
  var vd=getVirtualDate(G&&G.state?G.state.day:1);
  var first=new Date(CAL.y,CAL.m,1);
  var days=new Date(CAL.y,CAL.m+1,0).getDate();
  var start=first.getDay();
  var t=$('#cal-title');if(t)t.textContent=CAL.y+'年'+(CAL.m+1)+'月';
  var h='';
  for(var i=0;i<start;i++)h+='<div class="cal-cell empty"></div>';
  for(var d=1;d<=days;d++){
    var isGame=(CAL.y===vd.getFullYear()&&CAL.m===vd.getMonth()&&d===vd.getDate());
    h+='<div class="cal-cell '+(isGame?'today':'')+'">'+d+
      (isGame?'<div class="cal-tag">游戏日</div>':'')+'</div>';
  }
  $('#cal-grid').innerHTML=h;
  renderCalClock();
}
function openCal(){
  calToday();
  var sc=$('#screen-cal');if(!sc)return;
  sc.style.display='flex';
  renderCal();
  if(calTimer)clearInterval(calTimer);
  calTimer=setInterval(renderCalClock,1000);
}
function closeCal(){
  var sc=$('#screen-cal');if(sc)sc.style.display='none';
  if(calTimer){clearInterval(calTimer);calTimer=null}
}
function calNav(d){
  CAL.m+=d;
  if(CAL.m<0){CAL.m=11;CAL.y--}
  if(CAL.m>11){CAL.m=0;CAL.y++}
  renderCal();
}
function showIntro(t,b){$('#intro-title').innerHTML=t;$('#intro-body').innerHTML=b;$('#intro-modal').style.display='flex';ri($('#intro-modal'))}
function closeIntro(){
  $('#intro-modal').style.display='none';
  /* Trigger new player tutorial on first entry */
  setTimeout(function(){if(typeof Tutorial!=='undefined'&&Tutorial.shouldShow())Tutorial.start()},300);
}

/* ==================== New Player Tutorial System ==================== */
/* steps 文案已外置到 data/config.json → tutorial.steps，由 ensureDataLoaded() 注入 */
var Tutorial={
  steps:[],cur:0,active:false,
  shouldShow:function(){
    try{return !localStorage.getItem('cze_tutorial_done')}catch(e){return true}
  },
  markDone:function(){
    try{localStorage.setItem('cze_tutorial_done','1')}catch(e){}
  },
  start:function(){
    this.cur=0;this.active=true;
    $('#tutorial-overlay').style.display='flex';
    this.show();
  },
  show:function(){
    if(this.cur<0||this.cur>=this.steps.length){this.end();return}
    var step=this.steps[this.cur];
    var ov=$('#tutorial-overlay');
    var bub=$('#tutorial-bubble');
    var sp=$('#tutorial-spotlight');
    var arrow=$('#tutorial-arrow');
    /* Build dots */
    var dotsHtml='';
    for(var i=0;i<this.steps.length;i++){
      dotsHtml+='<span class="tb-dot'+(i===this.cur?' on':'')+'"></span>';
    }
    $('#tutorial-dots').innerHTML=dotsHtml;
    /* Build buttons */
    var btnsHtml='';
    if(this.cur>0)btnsHtml+='<button class="tb-btn tb-btn-skip" onclick="Tutorial.prev()">'+icon('arrow-left',14)+' 上一步</button>';
    else btnsHtml+='<button class="tb-btn tb-btn-skip" onclick="Tutorial.end()">跳过引导</button>';
    if(this.cur<this.steps.length-1){
      btnsHtml+='<button class="tb-btn tb-btn-next" onclick="Tutorial.next()">下一步 '+icon('arrow-right',14)+'</button>';
    }else{
      btnsHtml+='<button class="tb-btn tb-btn-next" onclick="Tutorial.end()">开始经营 '+icon('check-circle',14)+'</button>';
    }
    $('#tutorial-btns').innerHTML=btnsHtml;
    /* Content */
    $('#tutorial-icon').innerHTML=icon(step.icon,28);
    $('#tutorial-title').innerHTML=step.title;
    $('#tutorial-body').innerHTML=step.body;
    /* Positioning */
    if(!step.target||step.placement==='center'){
      /* Center the bubble */
      bub.style.cssText='position:relative;top:50%;left:50%;transform:translate(-50%,-50%);max-width:340px;width:90%';
      sp.style.display='none';
      arrow.style.display='none';
      ov.style.justifyContent='center';
      ov.style.alignItems='center';
      ov.style.background='rgba(0,0,0,.6)';
    }else{
      var el=document.querySelector(step.target);
      if(el){
        var rect=el.getBoundingClientRect();
        /* Show spotlight - overlay becomes transparent, spotlight handles dimming */
        ov.style.background='transparent';
        sp.style.display='block';
        sp.style.left=(rect.left-6)+'px';
        sp.style.top=(rect.top-6)+'px';
        sp.style.width=(rect.width+12)+'px';
        sp.style.height=(rect.height+12)+'px';
        /* Position bubble near target */
        ov.style.justifyContent='center';
        ov.style.alignItems='flex-start';
        var bubW=320;
        var bubH=240;
        var cx=rect.left+rect.width/2;
        var cy=rect.top+rect.height/2;
        var placeY,placeX;
        if(step.placement==='top'){
          placeY=rect.top-bubH-20;
          if(placeY<10)placeY=rect.bottom+20;
        }else if(step.placement==='bottom'){
          placeY=rect.bottom+20;
          if(placeY+bubH>window.innerHeight-10)placeY=rect.top-bubH-20;
        }else{
          placeY=cy-bubH/2;
        }
        placeX=cx-bubW/2;
        if(placeX<10)placeX=10;
        if(placeX+bubW>window.innerWidth-10)placeX=window.innerWidth-bubW-10;
        if(placeY<10)placeY=10;
        if(placeY+bubH>window.innerHeight-10)placeY=window.innerHeight-bubH-10;
        bub.style.cssText='position:absolute;left:'+placeX+'px;top:'+placeY+'px;max-width:'+bubW+'px;width:'+bubW+'px;transform:none';
        /* Arrow */
        var ax=cx-placeX;
        if(placeY>rect.bottom){
          /* bubble is below target, arrow points up */
          arrow.style.cssText='display:block;left:'+(ax-8)+'px;top:-10px;border-color:transparent transparent #fff transparent';
        }else if(placeY+bubH<rect.top){
          /* bubble is above target, arrow points down */
          arrow.style.cssText='display:block;left:'+(ax-8)+'px;bottom:-10px;border-color:#fff transparent transparent transparent';
        }else{
          arrow.style.display='none';
        }
      }else{
        /* Fallback to center if element not found */
        bub.style.cssText='position:relative;top:50%;left:50%;transform:translate(-50%,-50%);max-width:340px;width:90%';
        sp.style.display='none';
        arrow.style.display='none';
        ov.style.justifyContent='center';
        ov.style.alignItems='center';
        ov.style.background='rgba(0,0,0,.6)';
      }
    }
  },
  next:function(){
    this.cur++;
    if(this.cur>=this.steps.length){this.end();return}
    this.show();
  },
  prev:function(){
    this.cur--;
    if(this.cur<0)this.cur=0;
    this.show();
  },
  end:function(){
    this.active=false;
    this.cur=0;
    $('#tutorial-overlay').style.display='none';
    $('#tutorial-spotlight').style.display='none';
    $('#tutorial-overlay').style.background='rgba(0,0,0,.6)';
    this.markDone();
  }
};
/* 小游戏期间打烊的几天先攒着，退出时并成一张总账：
   金额类逐日相加，评分取最后一天，提示文案去重后保留 */
function mergeDaySettles(list){
  if(!list||!list.length)return null;
  var first=list[0],last=list[list.length-1];
  function sum(k){
    var t=0;
    list.forEach(function(d){t+=(typeof d[k]==='number'&&isFinite(d[k])?d[k]:0)});
    return t;
  }
  function mergeText(k,sep){
    var out=[],seen={};
    list.forEach(function(d){
      String(d[k]||'').split('\n').forEach(function(x){
        x=x.trim();if(!x||seen[x])return;seen[x]=1;out.push(x);
      });
    });
    return out.join(sep||'；');
  }
  return {
    day:last.day,
    dayFrom:first.day,
    daySpan:Math.max(1,last.day-first.day+1),
    backlog:true,
    income:sum('income'),salary:sum('salary'),brandFee:sum('brandFee'),rawMat:sum('rawMat'),
    platformFee:sum('platformFee'),packaging:sum('packaging'),rent:sum('rent'),
    propertyFee:sum('propertyFee'),utility:sum('utility'),depreciation:sum('depreciation'),
    foodWaste:sum('foodWaste'),
    completed:sum('completed'),expired:sum('expired'),abandoned:sum('abandoned'),
    rating:(typeof last.rating==='number'?last.rating:5),
    costProgress:last.costProgress,locationName:last.locationName,season:last.season,
    eventMsg:mergeText('eventMsg'),compMsg:mergeText('compMsg')
  };
}
function showDaySettlement(d){
  var s=G.state;
  var isBacklog=!!d.backlog,daySpan=d.daySpan||1,dayFrom=d.dayFrom||d.day;
  var rangeLabel=(dayFrom!==d.day)?('第'+dayFrom+'–'+d.day+'日'):('第'+d.day+'日');
  var income=d.income,salary=d.salary,brandFee=d.brandFee,rawMat=d.rawMat;
  var platformFee=d.platformFee||0,packaging=d.packaging||0;
  var rent=d.rent||0,propertyFee=d.propertyFee||0;
  var utility=d.utility||0,depreciation=d.depreciation||0,foodWaste=d.foodWaste||0;
  var net=income-salary-brandFee-rawMat-platformFee-packaging-rent-propertyFee-utility-depreciation-foodWaste;
  var h='';
  var seasonLabel=d.season?(SEASON_DATA[d.season]||{}).name||'':'';
  /* 账本体 */
  var mt=$('#day-modal .modal');if(mt)mt.classList.add('ledger');
  var ht=$('#day-title');if(ht)ht.classList.add('ledger-head');
  h+='<div class="ledger-shop">'+(s.shopName||'我的小店')+'<small>流 水 账</small></div>';
  h+='<div class="ledger-body">';
  function lr(n,ic,v,positive){
    h+='<div class="ledger-row"><span class="lr-n">'+ic+' '+n+'</span><span class="lr-dots"></span><span class="lr-v '+(positive?'in':'out')+'">'+(positive?'+':'-')+formatMoney(Math.abs(v))+'</span></div>';
  }
  lr('营业收入',icon('trending-up',14),income,true);
  if(salary>0)lr('员工工资',icon('users',14),salary);
  if(brandFee>0)lr('品牌加盟费',icon('briefcase',14),brandFee);
  if(rawMat>0)lr('原料采购',icon('package',14),rawMat);
  if(platformFee>0)lr('平台抽佣',icon('percent',14),platformFee);
  if(packaging>0)lr('打包耗材',icon('package',14),packaging);
  if(rent>0)lr('店铺租金',icon('home',14),rent);
  if(propertyFee>0)lr('物业管理费',icon('building',14),propertyFee);
  if(utility>0)lr('水电费',icon('zap',14),utility);
  if(depreciation>0)lr('设备折旧',icon('wrench',14),depreciation);
  if(foodWaste>0)lr('食材报废',icon('trash-2',14),foodWaste);
  h+='</div>';
  h+='<div class="ledger-net"><span class="ledger-seal">'+(isBacklog?'期间<br>结算':'当日<br>结算')+'</span><span class="ln-n">'+(isBacklog?'期间净利':'本日净利')+'</span><span class="ln-v '+(net>=0?'in':'out')+'">'+(net>=0?'+':'-')+formatMoney(Math.abs(net))+'</span></div>';
  h+='<div class="ledger-stats">';
  h+='<div class="ledger-stat"><div class="ledger-stat-num" style="color:#1b5e20">'+d.completed+'</div><div class="ledger-stat-label">完成订单</div></div>';
  h+='<div class="ledger-stat"><div class="ledger-stat-num" style="color:#b0341f">'+d.expired+'</div><div class="ledger-stat-label">超时订单</div></div>';
  h+='<div class="ledger-stat"><div class="ledger-stat-num">'+d.rating.toFixed(1)+'</div><div class="ledger-stat-label">店铺评分</div></div>';
  h+='<div class="ledger-stat"><div class="ledger-stat-num" style="color:#6d4c2f">'+formatMoney(s.money)+'</div><div class="ledger-stat-label">账上资金</div></div>';
  h+='</div>';
  if(isBacklog)h+='<div class="ledger-note" style="background:rgba(33,150,243,.1);color:#1565C0">'+icon('swords',13)+' 小游戏期间共自动结算 '+daySpan+' 天，以下为合并账目</div>';
  if(d.compMsg)h+='<div class="ledger-note warn">'+icon('alert-triangle',13)+' 同行竞争：'+d.compMsg+'</div>';
  if(d.abandoned>0)h+='<div class="ledger-note warn">'+icon('user-x',13)+' 期间 '+(d.abandoned)+' 位顾客久等退单，拉低了店铺评分</div>';
  if(d.eventMsg)h+='<div class="ledger-note">'+icon('zap',13)+' '+d.eventMsg+'</div>';
  if(isBacklog)h+='<div class="ledger-note">'+icon('calendar',13)+' '+rangeLabel+'（'+getSeasonLabel(d.day)+'）营业完成 · 小游戏期间自动推进</div>';
  else h+='<div class="ledger-note">'+icon('calendar',13)+' '+formatVirtualDate(d.day)+'（'+getSeasonLabel(d.day)+'）营业完成</div>';
  var foot=[];
  if(s.bizHoursLabel)foot.push('营业时长 '+s.bizHoursLabel);
  foot.push('平台抽佣·租金·物业·水电·折旧·食材均已计入');
  h+='<div class="ledger-foot">'+foot.join(' · ')+'</div>';
  if(ht){
    if(isBacklog)ht.innerHTML='<div class="lh-t">'+(daySpan>1?'多 日 流 水 账':'营 业 流 水 账')+'</div><div class="lh-s">'+rangeLabel+' · 共'+daySpan+'天 · 小游戏期间自动结算</div>';
    else ht.innerHTML='<div class="lh-t">每 日 流 水 账</div><div class="lh-s">第'+d.day+'日 · '+formatVirtualDate(d.day)+'</div>';
  }
  $('#day-body').innerHTML=h;
  $('#day-continue-btn').textContent=isBacklog?'回到经营':'开始第'+(d.day+1)+'天';
  $('#day-modal').style.display='flex';
  G._paused=true;
  G._settleBacklog=isBacklog;
  ri($('#day-modal'));
}
function closeDaySettlement(){$('#day-modal').style.display='none';G._paused=false;
  /* 开门时刻：0 点也是合法值（全天营业），不能按假值兜底成 9 点 */
  if(G.state&&!G._settleBacklog){G.state.dayTimer=(typeof G.state.bizOpenHour==='number'?G.state.bizOpenHour:0)*12;}
  G._settleBacklog=false;
}

