/* ===== B-3 存档向后兼容 =====
   旧档（或未来新增字段前的档）缺字段时，用 config.json 的 stateDefaults 补全。
   只补「不存在的键」，绝不覆盖玩家已有进度；对象类型字段递归补全。 */
/* 数值查表：等级经验曲线 / 等级解锁文案 / 心情阈值 / 疲劳配色，均来自 config.json */
function levelExpNeed(lv){
  var c=(CONFIG&&CONFIG.level)||{};
  return Math.round((c.expBase!=null?c.expBase:100)+lv*(c.expLinear!=null?c.expLinear:80)+lv*lv*(c.expQuad!=null?c.expQuad:30));
}
function levelUnlockMsg(lv){
  var c=(CONFIG&&CONFIG.level)||{};
  if(c.unlockMessages&&c.unlockMessages[String(lv)])return c.unlockMessages[String(lv)];
  if(lv===3)return ' 解锁：平台抽佣+打包耗材';
  if(lv===4)return ' 解锁：租金+物业费';
  if(lv===5)return ' 解锁：水电+折旧+损耗';
  return '';
}
function salaryMoodOf(ratio){
  var _sm=(CONFIG&&CONFIG.staff)||{};
  var mr=_sm.moodRatios||[{min:2.5,mood:'terrible'},{min:2,mood:'bad'},{min:1.5,mood:'great'},{min:1.2,mood:'good'},{min:0.9,mood:'normal'},{min:0.7,mood:'bad'},{min:0.5,mood:'terrible'}];
  for(var i=0;i<mr.length;i++){if(ratio>=mr[i].min)return mr[i].mood;}
  return _sm.moodFallback||'angry';
}
/* v33: 工资口径统一。旧实现把 200/0.3/3/333 写死在 adjustSalary 里，
   data/config.json 的 staff 段（以及上面这个 salaryMoodOf）没有任何调用点，形同虚设；
   而全游戏日薪只有 35~180，绝对下限 200 高于每一个人，
   于是 base=50 的允许区间算出来是 [200,150]（下限>上限），四个按钮一律把工资顶到 200 且再也降不下来。 */
function _num(v,d){return (typeof v==='number'&&isFinite(v))?v:d}
function staffCfg(){
  var _s=(CONFIG&&CONFIG.staff)||{};
  return {minRatio:_num(_s.salaryMinRatio,0.3),maxRatio:_num(_s.salaryMaxRatio,3),
    minFloor:_num(_s.salaryMinFloor,0),slack:_num(_s.slackingSalary,333),
    base:_num(_s.baseSalary,0)};
}
/* v42: 统一基准工资。CONFIG.staff.baseSalary>0 时，所有员工（入职 / 雇佣 / 收购带过来的 /
   挖角来的，以及人才市场、猎头名单上还没雇的那些）的基准工资和日薪都取这一个数；
   设回 0 或删掉这个键，就恢复"每人按 data 里自己的 salary 入职"的旧口径。
   可调区间、心情比例仍然按每人自己的 baseSalary 算，所以统一基准之后
   每个人的可调范围都是 base*0.3 ~ base*3（默认 60~600）。 */
function wageBase(){return staffCfg().base}
/* 就地套用统一基准；返回同一个对象，方便塞进 push(...) 里 */
function withWageBase(o){
  if(!o)return o;
  var b=wageBase();
  if(!(typeof b==='number'&&isFinite(b)&&b>0))return o;
  o.baseSalary=b;o.salary=b;
  return o;
}
/* 人才市场和猎头名单上的人"还没入职"，但卡片上写的日薪必须和入职后一致——
   否则玩家看着"日薪120"把人招进来，第二天账单变成200。这里克隆一份再套基准，
   不污染 TALENT_POOL / HUNT_TARGETS 这两个全局常量（换一批时还要重新抽它们）。 */
function wageClone(o){
  if(!o)return o;
  var c;
  try{c=JSON.parse(JSON.stringify(o))}catch(err){c=o}
  return withWageBase(c);
}
function wageCloneList(arr){
  var out=[];
  for(var i=0;i<(arr||[]).length;i++)out.push(wageClone(arr[i]));
  return out;
}
/* 基准工资：baseSalary 缺失或坏值时退回当前工资。
   注意必须在改写 e.salary 之前取好基准再传下去——旧代码改完工资才去读 base，
   base 缺失时拿到的就是新工资，ratio 恒等于 1，加薪永远不改变心情。 */
function empSalaryBase(e){
  if(!e)return 0;
  /* v42: 统一基准工资开启时，基准就是 CONFIG.staff.baseSalary 这一个数，
     不再看每个人自己的历史值（显示、心情比例、可调区间全都跟着它走） */
  var gb=wageBase();
  if(gb>0)return gb;
  var b=e.baseSalary;
  if(typeof b==='number'&&isFinite(b)&&b>0)return b;
  var s=e.salary;
  return (typeof s==='number'&&isFinite(s)&&s>0)?s:0;
}
/* 可调区间，恒满足 lo<=hi：绝对下限（保命工资）只在不超过该员工自身基准时才抬高下限——
   一旦绝对下限高于基准，它就变成"降薪反而涨钱"的来源（这正是旧版 200 下限把 50 日薪顶成 200 的原因）。
   salaryMaxRatio<=0（如 0）= 涨薪无上限：hi 取 Infinity，adjustSalary / 留人加薪里的
   Math.min(hi,...) 钳制自动失效；降薪下限、心情比例、摸鱼惩罚均不受影响。 */
function salaryBandOf(base){
  var c=staffCfg();
  base=Math.max(1,_num(base,1));
  var lo=Math.max(1,Math.floor(base*c.minRatio));
  var hi=c.maxRatio>0?Math.max(lo,Math.ceil(base*c.maxRatio)):Infinity;
  if(c.minFloor>0&&c.minFloor<=base)lo=Math.max(lo,c.minFloor);
  return [lo,hi];
}
/* 心情合成：工资维度 + 疲劳维度（旧实现是 adjustSalary 直接覆盖 e.mood，点一下 +1 就能把累垮的人刷回正常） */
var MOOD_SEVERITY={great:0,good:1,normal:2,bad:3,terrible:4,angry:5};
function moodSev(m){return (m in MOOD_SEVERITY)?MOOD_SEVERITY[m]:2}
/* 只要有一方不满（比 normal 差）就取更差的那方——涨钱买不动过度疲劳；
   双方都不差时取更好的那方——否则"疲劳=normal"会把加薪的干劲加成整个吃掉，加薪永远不涨效率 */
function combineMood(a,b){
  var sa=moodSev(a),sb=moodSev(b);
  if(sa>2||sb>2)return sa>=sb?(a||'normal'):(b||'normal');
  return sa<=sb?(a||'normal'):(b||'normal');
}
function fatigueColorOf(f){
  var _sm=(CONFIG&&CONFIG.staff)||{};
  var stops=_sm.fatigueColorStops||[{min:80,color:'#B71C1C'},{min:60,color:'#FF5722'},{min:40,color:'#FF9800'},{min:20,color:'#FFC107'}];
  for(var i=0;i<stops.length;i++){if(f>=stops[i].min)return stops[i].color;}
  return _sm.fatigueColorFallback||'#4CAF50';
}
function getStateDefaults(){return (CONFIG&&CONFIG.stateDefaults)||{}}
/* 类型坏了就当缺失处理：NaN 存盘会变成 null，手改/串版本的存档还可能把数组写成对象。
   这类值留着会让 render 抛异常（存档再也打不开）或让天数判断永远不成立（日子再也不结算）。
   注意 0 是合法值，不能按"假值"处理。 */
function _stateFieldBroken(d,v){
  if(v===undefined||v===null)return true;
  if(typeof d==='number')return typeof v!=='number'||!isFinite(v);
  if(Array.isArray(d))return !Array.isArray(v);
  if(d&&typeof d==='object')return typeof v!=='object'||Array.isArray(v);
  return false;
}
function mergeStateDefaults(state,defaults){
  if(!state||typeof state!=='object'||!defaults)return state;
  Object.keys(defaults).forEach(function(k){
    var d=defaults[k];
    if(!(k in state)||_stateFieldBroken(d,state[k])){
      try{state[k]=JSON.parse(JSON.stringify(d));}catch(e){state[k]=d;}
    }else if(d&&typeof d==='object'&&!Array.isArray(d)&&state[k]&&typeof state[k]==='object'&&!Array.isArray(state[k])){
      mergeStateDefaults(state[k],d);
    }
  });
  return state;
}

var _dataLoaded=false;
function ensureDataLoaded(cb){
  if(_dataLoaded){cb();return;}
  var left=DATA_FILES.length,finished=false;
  function one(){
    left--;
    if(left<=0&&!finished){finished=true;_dataLoaded=true;finalizeData();cb();}
  }
  for(var i=0;i<DATA_FILES.length;i++){
    (function(f){
      _loadDataJSON(f.url,function(d){
        if(d){try{f.apply(d);}catch(e){console.error('apply data failed',f.url,e);}}
        one();
      });
    })(DATA_FILES[i]);
  }
}

