// 从真实评价库获取评价
function getDBReview(stars,shopTypeId){
  var ft=SHOP_FOOD_MAP[shopTypeId]||'中餐';
  var cat=STAR_CAT[stars]||'medium';
  var pool=WAIMAI_REVIEWS.filter(function(r){return r.foodType===ft&&r.category===cat});
  if(pool.length===0)pool=WAIMAI_REVIEWS.filter(function(r){return r.category===cat});
  if(pool.length===0)pool=WAIMAI_REVIEWS;
  var picked=pool[Math.floor(Math.random()*pool.length)];
  // 50%概率用真实评价，50%用原有梗评价，混合使用
  if(Math.random()<0.5&&REVIEWS[stars]&&REVIEWS[stars].length>0){
    return {text:randItem(REVIEWS[stars]),rating:stars};
  }
  return {text:picked.text,rating:picked.rating};
}

