/* 特殊形式回复：红包有真实花费与评价加成，幽默化解零成本活跃气氛 */
/* 数据已外置 → data/ 下 JSON，由 ensureDataLoaded() 注入 */
/* 收到红包后的专属感谢语 */
/* 数据已外置 → data/ 下 JSON，由 ensureDataLoaded() 注入 */
var _CHAT_REPLY_CACHE={};
/* 取对方最后一条消息 */
function chatLastThemText(chat){
  var t='';
  (chat.messages||[]).forEach(function(m){if(m.from==='them')t=m.text});
  return t||chat.text||'';
}
function detectChatTopics(text){
  var scored=[];
  CHAT_TOPIC_RULES.forEach(function(r){
    var n=0;
    r.w.forEach(function(w){n+=countWord(text,w)});
    if(n>0)scored.push({key:r.key,n:n});
  });
  scored.sort(function(a,b){return b.n-a.n});
  return scored.slice(0,3).map(function(x){return x.key});
}
/* 生成与对方消息对应的回复选项；每回复一轮换一批
   返回 [{text,kind:'text'|'redpacket'|'humor',tag,cost,rate}] */
function buildChatReplyOptions(chat){
  var text=chatLastThemText(chat);
  var myCount=(chat.messages||[]).filter(function(m){return m.from==='me'}).length;
  var ck=chat.id+'_'+myCount+'_'+text.length+'_'+text.slice(0,8);
  if(_CHAT_REPLY_CACHE[ck])return _CHAT_REPLY_CACHE[ck];
  var pools=[];
  var topics=detectChatTopics(text);
  topics.forEach(function(k){
    var l=CHAT_REPLY_TOPICS[k];
    if(l&&l.length)pools.push(l);
  });
  var out=[],used={};
  /* 贴合事由的文字回复（最多 3 条） */
  if(pools[0])fillReplyOptions(pools[0],2,out,used,'');
  if(pools[1])fillReplyOptions(pools[1],1,out,used,'');
  for(var q=0;q<pools.length&&out.length<3;q++)fillReplyOptions(pools[q],3-out.length,out,used,'');
  var fb=CHAT_REPLY_FALLBACK[chat.role]||CHAT_REPLY_FALLBACK.customer;
  if(!pools.length)fillReplyOptions(fb,3,out,used,'');
  else if(out.length<3)fillReplyOptions(fb,3-out.length,out,used,'');
  /* 给每条文字选项标上它来自哪个事由，对方下一句才能接得住 */
  var textTopic={};
  topics.forEach(function(k){
    (CHAT_REPLY_TOPICS[k]||[]).forEach(function(s){textTopic[s]=k});
  });
  out=out.map(function(s){return {text:s,kind:'text',tag:'',cost:0,rate:0,topic:textTopic[s]||topics[0]||'general'}});
  /* 特殊形式：红包 + 幽默化解 */
  var sp=CHAT_SPECIAL_OPTIONS[chat.role];
  if(sp)out=out.concat(sp.map(function(o){
    var c={};for(var k in o)c[k]=o[k];
    if(!c.topic)c.topic=topics[0]||'general';
    return c;
  }));
  _CHAT_REPLY_CACHE[ck]=out;
  return out;
}
/* 订单卡里的“共 N 件”：新存档用 items 的数量，旧存档退回按 + 拆菜名 */
function chatOrderItemCount(orderInfo){
  if(!orderInfo)return 0;
  var items=orderInfo.items||[];
  if(items.length){
    return items.reduce(function(n,it){return n+(Number(it.qty)||1)},0);
  }
  if(orderInfo.dishNames){
    return String(orderInfo.dishNames).split('+').filter(function(n){return !!n}).length;
  }
  return 0;
}
/* 拟外卖小票：逐项菜品/数量/小计 + 下单时间 + 合计。
   旧存档没有 items/placedAt 也能画，只是不显示逐项价格。 */
function chatOrderCardHtml(chat,roleColor){
  var o=chat.orderInfo||{};
  var metas={
    customer:{kind:'外卖订单',icon:'shopping-bag',totalLabel:'合计'},
    rider:{kind:'配送单',icon:'bike',totalLabel:'客付'},
    staff:{kind:'关联订单',icon:'clipboard-list',totalLabel:'合计'}
  };
  var meta=metas[chat.role]||metas.customer;
  var items=(o.items||[]).slice();
  if(!items.length&&o.dishNames){
    items=String(o.dishNames).split('+').filter(function(n){return !!n}).map(function(n){
      return {name:n,qty:1,price:null};
    });
  }
  var count=chatOrderItemCount(o);
  var time=o.placedAt||chat.lastTime||chat.time||'';
  var h='<div class="chat-order-card" style="--co-role:'+(roleColor||'#FF6B35')+'">';
  h+='<div class="co-top"><div class="co-brand">'+
    '<span class="co-ic">'+icon(meta.icon,15)+'</span>'+
    '<div class="co-title"><span class="co-kind">'+meta.kind+'</span>'+
    '<span class="co-no">#'+esc(o.orderId||'--')+'</span></div></div>';
  if(time)h+='<span class="co-time">'+icon('clock',11)+' '+esc(time)+'</span>';
  h+='</div>';
  h+='<div class="co-items">';
  if(items.length){
    items.forEach(function(it){
      var qty=Number(it.qty)||1;
      var hasPrice=it.price!==null&&it.price!==undefined&&it.price!==''&&isFinite(Number(it.price));
      h+='<div class="co-item"><span class="co-name">'+esc(it.name||'菜品')+'</span>'+
        '<span class="co-qty">×'+qty+'</span>'+
        (hasPrice?'<span class="co-line-price">¥'+formatMoney(Number(it.price)*qty)+'</span>':'')+
        '</div>';
    });
  }else{
    h+='<div class="co-item"><span class="co-name">'+esc(o.dishNames||'订单详情')+'</span></div>';
  }
  h+='</div>';
  h+='<div class="co-foot"><span class="co-count">'+(count?'共 '+count+' 件':'订单明细')+'</span>'+
    '<span class="co-total">'+meta.totalLabel+' <b><span class="co-currency">¥</span>'+formatMoney(o.price||0)+'</b></span></div>';
  h+='</div>';
  return h;
}
