// ===== v32: 预设回复与评价内容智能匹配 =====
// 先识别评价文本在吐槽/夸奖什么（异物卫生/食材新鲜/分量/口味/温度/包装/配送/出餐/服务/价格/甩锅型），
// 再按星级给出"跟内容对得上"的回复选项，避免所有差评都是同一句"万分抱歉"。
/* 数据已外置 → data/ 下 JSON，由 ensureDataLoaded() 注入 */
UNRELATED_REVIEWS.forEach(function(u){UNRELATED_REVIEW_TEXT[u.text]=1});

/* 话题识别规则：命中次数多的优先 */
/* 数据已外置 → data/ 下 JSON，由 ensureDataLoaded() 注入 */
/* 甩锅型差评特征：理由跟菜品本身无关 */
/* 数据已外置 → data/ 下 JSON，由 ensureDataLoaded() 注入 */
/* 甩锅型搞笑差评：跟菜无关，回复也得跟着"甩锅理由"走 */
/* wt=权重，越具体的理由权重越高，避免"骑手"把"打游戏/猫"等理由吃掉 */
/* 数据已外置 → data/ 下 JSON，由 ensureDataLoaded() 注入 */
/* 数据已外置 → data/ 下 JSON，由 ensureDataLoaded() 注入 */
/* 各话题按星级语气的回复库，{dish} 会替换成评价对应的菜品名 */
/* 数据已外置 → data/ 下 JSON，由 ensureDataLoaded() 注入 */
/* 商业类评价：按具体动作（收购/卖店/挂牌/招商/成交）给对应口径 */
/* 数据已外置 → data/ 下 JSON，由 ensureDataLoaded() 注入 */
var _REVIEW_REPLY_CACHE={};

function reviewToneKey(stars){return stars>=4?'good':(stars===3?'mid':'bad')}
/* 识别评价内容涉及的话题，按命中权重排序 */
function detectReviewTopics(rv){
  var text=rv.text||'';
  var isUnrelated=!!UNRELATED_REVIEW_TEXT[text];
  if(!isUnrelated){
    for(var m=0;m<UNRELATED_MARKERS.length;m++){
      if(text.indexOf(UNRELATED_MARKERS[m])>=0){isUnrelated=true;break}
    }
  }
  if(isUnrelated){
    var best=null,bestScore=0;
    UNRELATED_SUB_RULES.forEach(function(sr){
      var n=0;
      sr.w.forEach(function(w){n+=countWord(text,w)});
      var sc=n*(sr.wt||1);
      if(sc>bestScore){bestScore=sc;best=sr.key}
    });
    return best?[best,'unrelated']:['unrelated'];
  }
  var scored=[];
  REVIEW_TOPIC_RULES.forEach(function(r){
    /* 低分评价不走"花式夸奖"话题，避免反讽被当成夸奖 */
    if((rv.stars||3)<=2&&r.key==='praise')return;
    var n=0;
    r.w.forEach(function(w){if(text.indexOf(w)>=0)n++});
    if(n>0)scored.push({key:r.key,n:n});
  });
  scored.sort(function(a,b){return b.n-a.n});
  return scored.slice(0,3).map(function(x){return x.key});
}
function reviewTopicKeys(rv){
  if(!rv)return[];
  var ck=_REVIEW_REPLY_CACHE['k_'+rv.id];
  if(ck)return ck;
  var keys=detectReviewTopics(rv);
  _REVIEW_REPLY_CACHE['k_'+rv.id]=keys;
  return keys;
}
/* 从候选列表中随机取若干条填充结果（去重，{dish} 替换为菜品名） */
function countWord(text,w){
  var c=0,i=0;
  while((i=text.indexOf(w,i))>=0){c++;i+=w.length}
  return c;
}
function fillReplyOptions(list,n,out,used,dish){
  if(!list||n<=0)return;
  var arr=list.slice();
  while(arr.length&&n>0&&out.length<4){
    var s=String(arr.splice(Math.floor(Math.random()*arr.length),1)[0]).replace(/\{dish\}/g,dish);
    if(used[s])continue;
    used[s]=1;out.push(s);n--;
  }
}
function buildInvestReplyOptions(rv){
  var ck=_REVIEW_REPLY_CACHE['o_'+rv.id];
  if(ck)return ck;
  var t=rv.text||'',d=rv.dish||'',k='general';
  if(t.indexOf('成交')>=0)k='deal';
  else if(t.indexOf('收购')>=0||d.indexOf('收购')>=0)k='buy';
  else if(t.indexOf('挂牌')>=0||d.indexOf('挂牌')>=0)k='listing';
  else if(t.indexOf('入驻')>=0||t.indexOf('考察')>=0||t.indexOf('来看')>=0||d.indexOf('入驻')>=0)k='lease';
  else if(d.indexOf('出售')>=0||t.indexOf('卖')>=0)k='sell';
  /* 先用本场景话术，不足 4 条再用通用商业话术补齐 */
  var out=[],used={};
  function take(arr,n){
    arr=arr.slice();
    while(arr.length&&out.length<4&&n>0){
      var s=arr.splice(Math.floor(Math.random()*arr.length),1)[0];
      n--;
      if(!used[s]){used[s]=1;out.push(s)}
    }
  }
  take(INVEST_REPLY_TOPICS[k]||[],4);
  take(REVIEW_REPLY_OPTIONS_INVEST,4-out.length);
  _REVIEW_REPLY_CACHE['o_'+rv.id]=out;
  return out;
}
/* 生成 4 条与评价内容对应的回复选项 */
function buildReviewReplyOptions(rv){
  if(!rv)return[];
  if(rv.isInvest)return buildInvestReplyOptions(rv);
  var ck=_REVIEW_REPLY_CACHE['o_'+rv.id];
  if(ck)return ck;
  var tier=reviewToneKey(rv.stars);
  var keys=reviewTopicKeys(rv);
  var dish=rv.dish||'这道菜';
  var pools=[];
  keys.forEach(function(k){
    var t=REVIEW_REPLY_TOPICS[k];
    if(!t)return;
    var l=t[tier]||t.bad||t.good;
    if(l&&l.length)pools.push(l);
  });
  var out=[],used={};
  if(pools[0])fillReplyOptions(pools[0],2,out,used,dish);
  if(pools[1])fillReplyOptions(pools[1],1,out,used,dish);
  if(pools[2])fillReplyOptions(pools[2],1,out,used,dish);
  for(var q=0;q<pools.length&&out.length<4;q++)fillReplyOptions(pools[q],4-out.length,out,used,dish);
  /* 只有完全识别不出话题时才退回通用话术，且至少给满 4 条 */
  if(!pools.length)fillReplyOptions(REVIEW_REPLY_OPTIONS[rv.stars]||REVIEW_REPLY_OPTIONS[3],4,out,used,dish);
  else if(out.length<3)fillReplyOptions(REVIEW_REPLY_OPTIONS[rv.stars]||REVIEW_REPLY_OPTIONS[3],3-out.length,out,used,dish);
  _REVIEW_REPLY_CACHE['o_'+rv.id]=out;
  return out;
}


// v29: 生成与菜品关联的评论
// stars<=2 时有15%概率出完全不相关的搞笑低分评论
// 其余按40%概率出菜品关联模板评论，60%走原有getDBReview
function generateDishReview(dishName,stars,shopTypeId){
  // 低分评论有15%概率完全不相关
  if(stars<=2&&Math.random()<0.15){
    var ur=UNRELATED_REVIEWS[Math.floor(Math.random()*UNRELATED_REVIEWS.length)];
    return{text:ur.text,rating:ur.rating};
  }
  // 40%概率用菜品关联模板
  if(Math.random()<0.4&&DISH_REVIEW_TEMPLATES[stars]&&DISH_REVIEW_TEMPLATES[stars].length>0){
    var tpl=DISH_REVIEW_TEMPLATES[stars][Math.floor(Math.random()*DISH_REVIEW_TEMPLATES[stars].length)];
    var safeDish=dishName||'外卖';
    var text=tpl.replace(/\{dish\}/g,safeDish);
    return{text:text,rating:stars};
  }
  // 剩余走原有评价库
  return getDBReview(stars,shopTypeId);
}


