/* v26: 选品/供应链系统 — 原料类型绑定出餐效率和成本 */
/* 数据已外置 → data/ 下 JSON，由 ensureDataLoaded() 注入 */
/* 根据店铺类型获取选品列表 */
function getSupplyList(shopTypeId){
  var shop=SHOP_TYPES.find(function(s){return s.id===shopTypeId});
  if(!shop)return SUPPLY_TYPES.food;
  var cat=shop.type;
  if(cat==='饮品'||cat==='奶茶')return SUPPLY_TYPES.drink;
  if(cat==='面食'||cat==='面馆')return SUPPLY_TYPES.noodle;
  return SUPPLY_TYPES.food;
}
function getSupplyInfo(supplyId,shopTypeId){
  var list=getSupplyList(shopTypeId);
  return list.find(function(s){return s.id===supplyId})||list[0];
}

