function closeAbout(){var m=document.getElementById('about-modal');if(m)m.style.display='none'}
function loadSave(){
  var users=getUsers();
  var saves=[];
  for(var u in users){
    if(users[u].gameState){
      saves.push({name:u,savedAt:users[u].savedAt||0,gameState:users[u].gameState,money:users[u].gameState.money||0,day:users[u].gameState.day||1,rating:users[u].gameState.shopRating||5.0});
    }
  }
  if(saves.length===0){showToast('暂无存档，请先开始新游戏','error');return}
  if(saves.length===1){
    var s=saves[0];
    currentUser={name:s.name,money:s.gameState.money||1500,ach:users[s.name].ach||{}};
    ensureDataLoaded(function(){
      if(!G.loadGame(s.gameState)){currentUser=null;showToast('该存档数据已损坏，无法读取','error');return;}
      $('#screen-login').style.display='none';
      $('#screen-game').style.display='flex';
      setGameHUD(true);
      showToast('欢迎回来，'+esc(s.name)+'！进度已恢复','success');
    });
    return;
  }
  saves.sort(function(a,b){return(b.savedAt||0)-(a.savedAt||0)});
  var h='<div style="text-align:center;margin-bottom:16px"><div style="font-size:18px;font-weight:800">选择存档</div><div style="font-size:12px;color:var(--text-m);margin-top:4px">共'+saves.length+'个存档</div></div>';
  saves.forEach(function(s){
    var dt=s.savedAt?new Date(s.savedAt):null;
    var dtStr=dt?(dt.getMonth()+1)+'/'+dt.getDate()+' '+dt.getHours()+':'+(dt.getMinutes()<10?'0':'')+dt.getMinutes():'未知';
    h+='<div class="shop-sel-card" data-sname="'+esc(s.name)+'" onclick="loadSaveByName(this.dataset.sname)">'+
      '<div class="ss-ic" style="background:linear-gradient(135deg,#FF8C42,#FF6B35)"><span class="icon" data-i="user" data-s="22"></span></div>'+
      '<div class="ss-info"><div class="ss-name">'+esc(s.name)+'</div>'+
      '<div class="ss-desc">第'+s.day+'天 · 资金'+formatMoney(s.money)+' · 评分'+s.rating+'</div>'+
      '<div class="ss-bonus">保存于 '+dtStr+'</div></div>'+
      '<span class="icon" data-i="chevron-right" data-s="20" style="color:var(--text-m)"></span></div>';
  });
  h+='<div style="margin-top:12px"><button class="btn btn-gray" style="width:100%;padding:12px;font-size:15px;border-radius:14px" onclick="backToHome()"><span class="icon" data-i="arrow-left" data-s="16"></span> 返回首页</button></div>';
  $('#ls-home').style.display='none';
  $('#ls-nickname').style.display='none';
  var ls=$('#ls-saves');
  ls.innerHTML=h;
  ls.style.display='block';
  ri(ls);
}
function loadSaveByName(name){
  var users=getUsers();
  if(!users[name]||!users[name].gameState){showToast('存档不存在','error');return}
  var savedMoney=users[name].gameState.money,prevUser=currentUser;
  currentUser={name:name,money:(typeof savedMoney==='number'&&isFinite(savedMoney))?savedMoney:1500,ach:users[name].ach||{}};
  ensureDataLoaded(function(){
    if(!G.loadGame(users[name].gameState)){currentUser=prevUser;showToast('该存档数据已损坏，无法读取','error');return;}
    $('#screen-login').style.display='none';
    $('#screen-game').style.display='flex';
    setGameHUD(true);
    showToast('欢迎回来，'+esc(name)+'！进度已恢复','success');
  });
}
function saveUser(){
  if(!currentUser)return;
  var users=getUsers();
  if(!users[currentUser.name])users[currentUser.name]={};
  users[currentUser.name].money=G.state?G.state.money:currentUser.money;
  users[currentUser.name].ach=G.ach||{};
  /* 存完整游戏进度 */
  if(G.state){
    try{
      users[currentUser.name].gameState=JSON.parse(JSON.stringify(G.state));
    }catch(e){}
  }
  users[currentUser.name].savedAt=Date.now();
  saveUsers(users);
}
