/* 已有昵称时点"开始新游戏"——直接进选址，跳过昵称输入 */
function quickStart(){
  var nick=getSavedNick();
  if(!nick){showNicknameInput();return}
  var users=getUsers();
  if(!users[nick]){users[nick]={money:1500,ach:{}};saveUsers(users)}
  currentUser={name:nick,money:1500,ach:{}};
  if(users[nick]&&users[nick].gameState){
    showToast('该昵称已有存档，新游戏将覆盖旧进度','warning');
  }
  showToast('欢迎回来，'+nick+'！选择你的起点','success');
  ensureDataLoaded(function(){showLocationSelect();});
}
/* 修改昵称——清除已保存昵称，回到输入界面 */
function resetNick(){
  try{localStorage.removeItem('cze_nick')}catch(e){}
  showNicknameInput();
  showToast('请输入新的昵称','info');
}
/* ===== 存档导出 / 导入（写本地磁盘文件，无需联网） ===== */
var SAVE_FILE_NAME='餐这儿存档.json';
/* 旧名「餐志儿」时期的存档文件：新文件读不到时回退去读，老玩家进度不丢 */
var SAVE_FILE_NAME_LEGACY='餐志儿存档.json';

function buildSaveExport(){
  return JSON.stringify({app:'餐这儿',kind:'save-export',version:1,
    exportedAt:new Date().toISOString(),users:getUsers()},null,2);
}
/* 兼容两种形态：新导出的 {users:{...}} 信封，以及旧版直接传输的 cze_users 整包 */
function parseSaveImport(text){
  var o=null;
  try{o=JSON.parse(text);}catch(e){return {err:'文件不是合法的 JSON'};}
  if(!o||typeof o!=='object'||Array.isArray(o))return {err:'文件内容不是存档数据'};
  var users=(o.kind==='save-export')?o.users:(o.users&&typeof o.users==='object'&&!Array.isArray(o.users)?o.users:o);
  if(!users||typeof users!=='object'||Array.isArray(users))return {err:'文件内容不是存档数据'};
  var names=Object.keys(users),valid=0;
  for(var i=0;i<names.length;i++){
    var v=users[names[i]];
    if(!v||typeof v!=='object'||Array.isArray(v))continue;
    /* 导入会覆盖本机全部存档，不能让一个坏条目把整套存档毁掉 */
    if(v.gameState!==undefined&&v.gameState!==null&&(typeof v.gameState!=='object'||Array.isArray(v.gameState)))
      return {err:'「'+esc(names[i])+'」的存档内容已损坏，本次导入已取消'};
    if(v.gameState||typeof v.money==='number')valid++;
  }
  if(!valid)return {err:'文件内容不是存档数据'};
  return {users:users};
}
function applySaveImport(parsed){
  if(parsed.err){showToast(parsed.err,'error');return;}
  var names=Object.keys(parsed.users);
  if(!names.length){showToast('存档文件里没有任何老板数据','error');return;}
  if(!confirm('将导入 '+names.length+' 个老板的存档，并覆盖本机现有全部存档，是否继续？'))return;
  saveUsers(parsed.users);
  showToast('存档导入成功，即将刷新','success');
  setTimeout(function(){location.reload();},900);
}
function exportSave(){
  var text=buildSaveExport();
  if(window.plus&&plus.io){writeSaveApp(text);return;}
  writeSaveWeb(text);
}
function importSave(){
  if(window.plus&&plus.io){showImportPicker();return;}
  readSaveWeb();
}
/* App 端导入存档：先选方式——自动读文档目录的固定文件，或手动从任意位置选文件
   （微信/QQ 收到的存档不在文档目录，必须给用户自己选的入口；私有目录回退产物也只有自动读取可达） */
function showImportPicker(){
  SFX.click();
  var m=document.getElementById('import-modal');
  if(!m){
    m=document.createElement('div');m.id='import-modal';
    m.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.5);z-index:310;display:none;align-items:center;justify-content:center;padding:16px';
    document.body.appendChild(m);
    /* 点遮罩关闭；卡片自身不响应 */
    m.addEventListener('click',function(e){if(e.target===m)closeImportPicker();});
  }
  m.innerHTML='<div style="background:#fff;border-radius:20px;max-width:340px;width:100%;padding:20px;box-shadow:0 20px 60px rgba(0,0,0,.2)">'+
    '<div style="font-weight:900;font-size:17px;color:var(--text-d);margin-bottom:2px;display:flex;align-items:center;gap:8px">'+icon('upload',18,'var(--primary)')+' 导入存档</div>'+
    '<div style="font-size:12px;color:var(--text-m);margin-bottom:14px">选择从哪里读取存档文件</div>'+
    '<button class="btn btn-success" style="width:100%;padding:12px;font-size:15px;border-radius:14px;margin-bottom:8px;display:flex;flex-direction:column;gap:3px" onclick="importFromDocs()">'+
      '<span style="display:flex;align-items:center;gap:6px">'+icon('archive',16)+' 从文档目录读取</span>'+
      '<span style="font-size:11px;font-weight:500;color:rgba(255,255,255,.85)">自动读取之前「导出存档」保存的文件</span>'+
    '</button>'+
    '<button class="btn btn-blue" style="width:100%;padding:12px;font-size:15px;border-radius:14px;display:flex;flex-direction:column;gap:3px" onclick="importPickFile()">'+
      '<span style="display:flex;align-items:center;gap:6px">'+icon('search',16)+' 选择文件…</span>'+
      '<span style="font-size:11px;font-weight:500;color:rgba(255,255,255,.85)">从微信、QQ、下载等任意位置选择</span>'+
    '</button>'+
    '<button class="btn" style="width:100%;padding:10px;font-size:14px;border-radius:12px;margin-top:8px;background:var(--bg);color:var(--text-m)" onclick="closeImportPicker()">取消</button>'+
    '</div>';
  m.style.display='flex';
}
function closeImportPicker(){var m=document.getElementById('import-modal');if(m)m.style.display='none'}
/* 先关弹窗再执行：toast(z-index 200) 会被弹窗(310)盖住；文件选择器也要在点击手势内触发 */
function importFromDocs(){closeImportPicker();readSaveApp();}
function importPickFile(){closeImportPicker();readSaveWeb();}
/* 分享存档：把最新存档交给系统分享面板（微信/QQ/蓝牙/隔空投送等）
   官方 plus.share.sendWithSystem 只支持文字/图片，文件分享走 Native.js，浏览器走 Web Share API */
function shareSave(){
  var text=buildSaveExport();
  if(window.plus&&plus.io){shareSaveApp(text);return;}
  shareSaveWeb(text);
}

/* --- 5+App：优先写系统公共「文档」目录 --- */
function saveEntryPath(entry){
  try{return plus.io.convertLocalFileSystemURL(entry.toLocalURL());}catch(e){return entry.name;}
}
/* Android 6+ 公共目录需要运行时存储权限，拿不到就交给下面的私有目录回退 */
function withStoragePermission(next){
  if(plus.android&&plus.android.requestPermissions&&/android/i.test(navigator.userAgent||'')){
    plus.android.requestPermissions(['android.permission.WRITE_EXTERNAL_STORAGE'],
      function(){next();},function(){next();});
    return;
  }
  next();
}
function writeFileEntry(entry,text,ok,fail){
  entry.createWriter(function(w){
    w.onerror=function(e){fail('写入失败('+(e&&e.code)+')');};
    function doWrite(){
      w.onwriteend=function(){w.onwriteend=null;ok();};
      w.write(text);
    }
    /* truncate 与 write 不能同时排队，等清空回调后再写 */
    w.onwriteend=function(){w.onwriteend=null;doWrite();};
    try{w.truncate(0);}catch(e){w.onwriteend=null;doWrite();}
  },function(e){fail('打开文件失败('+(e&&e.code)+')');});
}
function writeSaveApp(text){
  withStoragePermission(function(){
    /* 分区存储（Android 10+）可能拒绝公共目录写入，回退到应用私有文档目录并告知真实路径 */
    function toPrivate(){
      plus.io.requestFileSystem(plus.io.PRIVATE_DOC,function(fs){
        fs.root.getFile(SAVE_FILE_NAME,{create:true},function(entry){
          writeFileEntry(entry,text,function(){
            showToast('公共文档目录受系统限制，已保存到：'+saveEntryPath(entry),'warning');
          },function(msg){showToast(msg,'error');});
        },function(){showToast('无法创建存档文件','error');});
      },function(){showToast('无法访问应用文档目录','error');});
    }
    plus.io.requestFileSystem(plus.io.PUBLIC_DOCUMENTS,function(fs){
      fs.root.getFile(SAVE_FILE_NAME,{create:true},function(entry){
        writeFileEntry(entry,text,function(){
          showToast('已保存到文档目录：'+saveEntryPath(entry),'success');
        },toPrivate);
      },toPrivate);
    },toPrivate);
  });
}
function readSaveApp(){
  function fail(){showToast('读取存档失败','error');}
  function from(root,name,next){
    root.getFile(name,{},function(entry){
      entry.file(function(file){
        var r=new plus.io.FileReader();
        r.onloadend=function(){
          if(r.result==null){fail();return;}
          applySaveImport(parseSaveImport(String(r.result)));
        };
        r.onerror=fail;
        r.readAsText(file);
      },fail);
    },next);
  }
  function notFound(){showToast('文档目录里没有找到存档，请点「导入存档」→「选择文件」从其他位置导入','info');}
  /* 公共「文档」优先，读不到再回退应用私有目录，避免两份存档同时命中；
     两个位置都没有新文件时，再按旧文件名各找一遍（老版「餐志儿」导出的存档） */
  function fromPublic(name,next){
    plus.io.requestFileSystem(plus.io.PUBLIC_DOCUMENTS,function(fs){from(fs.root,name,next);},next);
  }
  function fromPrivate(name,next){
    plus.io.requestFileSystem(plus.io.PRIVATE_DOC,function(fs){from(fs.root,name,next);},next);
  }
  function tryLegacy(){
    fromPublic(SAVE_FILE_NAME_LEGACY,function(){fromPrivate(SAVE_FILE_NAME_LEGACY,notFound);});
  }
  fromPublic(SAVE_FILE_NAME,function(){fromPrivate(SAVE_FILE_NAME,tryLegacy);});
}

/* --- 5+App 分享存档：先写最新存档到应用私有文档目录（分享面板必然可读），再拉起系统分享 --- */
function shareSaveApp(text){
  plus.io.requestFileSystem(plus.io.PRIVATE_DOC,function(fs){
    fs.root.getFile(SAVE_FILE_NAME,{create:true},function(entry){
      writeFileEntry(entry,text,function(){
        var abs=saveEntryPath(entry);
        if(/iphone|ipad|ipod/i.test(navigator.userAgent||''))shareSaveIOS(abs);
        else shareSaveAndroid(abs);
      },function(msg){showToast(msg,'error');});
    },function(){showToast('无法创建存档文件','error');});
  },function(){showToast('无法访问应用文档目录','error');});
}
/* Android：Intent.ACTION_SEND + FileProvider content:// URI（Android 7+ 禁止 file:// 跨进程分享）
   authority 为 DCloud 云打包内置的 {包名}.dc.fileprovider（io.dcloud.common.util.DCloud_FileProvider），
   自定义基座/离线打包可能是 {包名}.fileprovider，依次尝试；全失败时退回 file://（仅 Android 6- 可用） */
function shareSaveAndroid(absPath){
  try{
    var main=plus.android.runtimeMainActivity();
    var FileCls=plus.android.importClass('java.io.File');
    var Intent=plus.android.importClass('android.content.Intent');
    var file=new FileCls(absPath);
    if(!file.exists()){showToast('存档文件不存在，请重试','error');return;}
    var uri=null,pkg=main.getPackageName(),FPClass=null;
    var cands=[pkg+'.dc.fileprovider',pkg+'.fileprovider'];
    try{FPClass=plus.android.importClass('androidx.core.content.FileProvider');}
    catch(e0){try{FPClass=plus.android.importClass('android.support.v4.content.FileProvider');}catch(e1){}}
    if(FPClass){
      for(var i=0;i<cands.length&&!uri;i++){
        try{uri=FPClass.getUriForFile(main,cands[i],file);}catch(e2){}
      }
    }
    if(!uri){
      try{uri=plus.android.importClass('android.net.Uri').fromFile(file);}catch(e3){}
    }
    if(!uri){showToast('分享失败，存档已保存在：'+absPath,'warning');return;}
    var intent=new Intent(Intent.ACTION_SEND);
    intent.setType('application/json');
    intent.putExtra(Intent.EXTRA_STREAM,uri);
    intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
    main.startActivity(Intent.createChooser(intent,'分享存档'));
  }catch(e){showToast('分享失败，存档已保存在：'+absPath,'warning');}
}
/* iOS：UIActivityViewController 直接分享沙盒里的文件 URL（隔空投送/存储到文件/微信等） */
function shareSaveIOS(absPath){
  try{
    var pios=plus.ios;
    var NSURL=pios.importClass('NSURL');
    var NSArray=pios.importClass('NSArray');
    var UIActivityViewController=pios.importClass('UIActivityViewController');
    var app=pios.importClass('UIApplication').sharedApplication();
    var keyWin=pios.invoke(app,'keyWindow');
    var rootVC=pios.invoke(keyWin,'rootViewController');
    var items=NSArray.arrayWithObject(NSURL.fileURLWithPath(absPath));
    var vc=pios.invoke(UIActivityViewController.alloc(),'initWithActivityItemsApplicationActivities',items,null);
    pios.invoke(rootVC,'presentViewControllerAnimatedCompletion',vc,true,null);
  }catch(e){showToast('分享失败，存档已保存在：'+absPath,'warning');}
}
/* --- 浏览器：Web Share API 支持分享文件时走系统分享，否则退回下载 --- */
function shareSaveWeb(text){
  try{
    var f=new File([text],SAVE_FILE_NAME,{type:'application/json'});
    if(navigator.share&&navigator.canShare&&navigator.canShare({files:[f]})){
      navigator.share({files:[f],title:'餐这儿存档'}).catch(function(e){
        if(e&&e.name==='AbortError')return;
        downloadSaveWeb(text);
      });
      return;
    }
  }catch(e){}
  downloadSaveWeb(text);
  showToast('当前浏览器不支持直接分享文件，已改为下载存档','info');
}

/* --- 浏览器：另存为对话框（可选到「文档」），不支持时回退为下载 --- */
function writeSaveWeb(text){
  if(window.showSaveFilePicker){
    window.showSaveFilePicker({suggestedName:SAVE_FILE_NAME,
      types:[{description:'存档文件',accept:{'application/json':['.json']}}]})
      .then(function(h){return h.createWritable().then(function(w){w.write(text);return w.close();});})
      .then(function(){showToast('存档已导出','success');})
      .catch(function(e){
        if(e&&e.name==='AbortError')return;
        downloadSaveWeb(text);
      });
    return;
  }
  downloadSaveWeb(text);
}
function downloadSaveWeb(text){
  try{
    var url=URL.createObjectURL(new Blob([text],{type:'application/json'}));
    var a=document.createElement('a');
    a.href=url;a.download=SAVE_FILE_NAME;
    document.body.appendChild(a);a.click();a.remove();
    setTimeout(function(){URL.revokeObjectURL(url);},1000);
    showToast('存档已导出到浏览器下载目录','success');
  }catch(e){showToast('导出失败：'+e.message,'error');}
}
function readSaveWeb(){
  var i=document.createElement('input');
  i.type='file';i.accept='.json,application/json';
  i.onchange=function(){
    var f=i.files&&i.files[0];
    if(!f)return;
    var r=new FileReader();
    r.onload=function(){applySaveImport(parseSaveImport(String(r.result||'')));};
    r.onerror=function(){showToast('读取文件失败','error');};
    r.readAsText(f);
  };
  i.click();
}
/* --- 验证码/密码登录相关函数已移除（简化为纯用户名登录）---
var verifyMethod='phone';
var verifyCode='';
var verifyCountdown=0;
var verifyCountdownTimer=null;
function switchLoginTab(tab,el){
  $$('.login-tab').forEach(function(t){t.classList.remove('active')});
  $$('.login-section').forEach(function(s){s.classList.remove('active')});
  if(el)el.closest('.login-tab').classList.add('active');
  $('#ls-'+tab).classList.add('active');
  ri($('#ls-'+tab));
}
function switchVerifyMethod(method,el){
  verifyMethod=method;
  $$('.vm-btn').forEach(function(b){b.classList.remove('active')});
  if(el)el.closest('.vm-btn').classList.add('active');
  var vi=$('#vm-icon'),vl=$('#vm-label'),vc=$('#verify-contact'),sc=$('#send-code-btn');
  if(method==='phone'){
    vi.setAttribute('data-i','phone');
    vl.textContent='手机号';
    vc.placeholder='请输入手机号';
    vc.maxLength=11;
    vc.type='tel';
    sc.innerHTML='<span class="icon" data-i="send" data-s="14"></span> 发送验证码';
  }else{
    vi.setAttribute('data-i','mail');
    vl.textContent='邮箱';
    vc.placeholder='请输入邮箱';
    vc.maxLength=50;
    vc.type='email';
    sc.innerHTML='<span class="icon" data-i="send" data-s="14"></span> 发送验证码';
  }
  vc.value='';
  $('#verify-code').value='';
  verifyCode='';
  ri(vi);
}
function sendVerifyCode(){
  var contact=$('#verify-contact').value.trim();
  if(verifyMethod==='phone'){
    if(!/^1[3-9]\d{9}$/.test(contact)){showToast('请输入正确的11位手机号','error');return}
  }else{
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact)){showToast('请输入正确的邮箱地址','error');return}
  }
  verifyCode=String(rand(100000,999999));
  var masked;
  if(verifyMethod==='phone'){
    masked=contact.substring(0,3)+'****'+contact.substring(7);
  }else{
    var at=contact.indexOf('@');
    masked=contact.substring(0,Math.min(2,at))+'****'+contact.substring(at);
  }
  showToast(icon('send',14)+' 验证码已发送至'+masked,'event');
  setTimeout(function(){
    showToast(icon('key',14)+' 验证码：'+verifyCode+'（模拟短信/邮件发送）','event');
  },800);
  verifyCountdown=60;
  var btn=$('#send-code-btn');
  btn.disabled=true;
  btn.textContent=verifyCountdown+'s后重发';
  if(verifyCountdownTimer)clearInterval(verifyCountdownTimer);
  verifyCountdownTimer=setInterval(function(){
    verifyCountdown--;
    if(verifyCountdown<=0){
      clearInterval(verifyCountdownTimer);
      verifyCountdownTimer=null;
      btn.disabled=false;
      btn.innerHTML='<span class="icon" data-i="send" data-s="14"></span> 发送验证码';
      ri(btn);
    }else{
      btn.textContent=verifyCountdown+'s后重发';
    }
  },1000);
}
function verifyCodeLogin(){
  var contact=$('#verify-contact').value.trim();
  var code=$('#verify-code').value.trim();
  if(!contact){showToast('请输入'+(verifyMethod==='phone'?'手机号':'邮箱'),'error');return}
  if(!code){showToast('请输入验证码','error');return}
  if(!verifyCode){showToast('请先发送验证码','error');return}
  if(code!==verifyCode){showToast('验证码错误，请重新输入','error');return}
  var users=getUsers();
  var userName=null;
  for(var u in users){
    if(verifyMethod==='phone'&&users[u].phone===contact){userName=u;break}
    if(verifyMethod==='email'&&users[u].email===contact){userName=u;break}
  }
  if(!userName){
    if(verifyMethod==='phone'){
      userName='用户'+contact.substring(7);
    }else{
      userName=contact.substring(0,contact.indexOf('@'));
    }
    var baseName=userName,c=1;
    while(users[userName]){userName=baseName+c;c++}
    users[userName]={pass:verifyCode,money:1500,ach:{}};
    if(verifyMethod==='phone')users[userName].phone=contact;
    else users[userName].email=contact;
    saveUsers(users);
    currentUser={name:userName,pass:verifyCode,money:1500,ach:{}};
    showToast('验证成功！自动注册：'+userName,'success');
  }else{
    currentUser={name:userName,money:users[userName].money||1500,ach:users[userName].ach||{}};
    showToast('验证成功！欢迎'+userName,'success');
  }
  if(verifyCountdownTimer){clearInterval(verifyCountdownTimer);verifyCountdownTimer=null}
  $('#verify-contact').value='';
  $('#verify-code').value='';
  verifyCode='';
  showShopSelect();
}
--- */
/* v28: 登录/选档页隐藏游戏内状态栏元素（时间、通知铃铛、静音）; 无内容时整条不占位 */
function setGameHUD(show){
  var d=show?'':'none';
  var sb=$('.status-bar');if(sb)sb.style.display=show?'flex':'none';
  var t=$('#sb-time');if(t)t.style.display=show?'flex':'none';
  var n=$('#notif-btn');if(n)n.style.display=d;
  var m=$('#mute-btn');if(m)m.style.display=show?'inline-flex':'none';
}
function logout(){
  /* 浮层挂在 body 上，只藏 #screen-game 会把它们压在登录页上面；结算浮层还带着 _paused */
  if(typeof pk!=='undefined'&&pk.running)pk.stop();
  if(typeof ww!=='undefined'&&ww.running)ww.stop();
  if(G._mon3d&&G._mon3d.mode){G._mon3d.closingDone=null;G.closeShop3D();}
  if(G.mall3d&&G.mall3d.id)G.closeMallPlan();
  Array.prototype.forEach.call(document.querySelectorAll('.modal-overlay'),function(m){m.style.display='none'});
  G._paused=false;G._skipNextSave=false;_miniExitKind=null;
  if(G.running)G.stop();
  saveUser();
  currentUser=null;
  setGameHUD(false);
  $('#screen-game').style.display='none';
  $('#screen-select').style.display='none';
  $('#ls-nickname').style.display='none';
  $('#ls-saves').style.display='none';
  $('#ls-home').style.display='block';
  $('#screen-login').style.display='flex';
  $('#login-user').value='';
  refreshHomeForNick();
  ri(document);
}
