/* 数据已外置 → data/ 下 JSON，由 ensureDataLoaded() 注入 */
function fmtHour(h){return(h<10?'0':'')+h+':00'}
function getBizHoursLabel(o,c){return fmtHour(o)+'-'+fmtHour(c===24?24:c)}
function getBizHoursTag(o,c){var hrs=c-o;if(hrs>=24)return'24小时通宵';if(o<=6&&c>=21)return'早鸟模式';if(o>=16)return'夜店模式';if(c-o>=15)return'拼命三郎';return'标准营业'}
function getBizDaysLabel(days){if(!days||!days.length)return'休';if(days.length>=7)return'每天';var parts=[];days.sort(function(a,b){return(a===0?7:a)-(b===0?7:b)}).forEach(function(d){parts.push(DOW_NAMES[d])});return parts.join('·')}
function buildDualSliderHTML(o,c){
  return '<div class="dual-slider" id="dual-slider">'+
    '<div class="ds-track"></div>'+
    '<div class="ds-fill" id="ds-fill"></div>'+
    '<div class="ds-handle ds-handle-open" id="ds-handle-open"></div>'+
    '<div class="ds-handle ds-handle-close" id="ds-handle-close"></div>'+
    '</div>'+
    '<div class="ds-ticks"><span>0</span><span>3</span><span>6</span><span>9</span><span>12</span><span>15</span><span>18</span><span>21</span><span>24</span></div>';
}
function buildDayPickerHTML(days){
  var h='<div class="day-picker" id="day-picker">';
  for(var i=1;i<=6;i++){var on=days.indexOf(i)>=0;h+='<div class="day-btn'+(on?' active':'')+'" onclick="toggleBizDay('+i+',true)">'+DOW_NAMES[i]+'</div>'}
  var on0=days.indexOf(0)>=0;h+='<div class="day-btn'+(on0?' active':'')+'" onclick="toggleBizDay(0,true)">'+DOW_NAMES[0]+'</div>';
  h+='</div>';
  return h;
}
function updateDualSliderUI(o,c){
  var slider=$('#dual-slider');if(!slider)return;
  var w=slider.offsetWidth;var pctO=o/24*100,pctC=c/24*100;
  var fill=$('#ds-fill');if(fill){fill.style.left=pctO+'%';fill.style.width=(pctC-pctO)+'%'}
  var ho=$('#ds-handle-open');if(ho)ho.style.left=pctO+'%';
  var hc=$('#ds-handle-close');if(hc)hc.style.left=pctC+'%';
  var pv=$('#biz-preview-hours');if(pv)pv.textContent=getBizHoursLabel(o,c);
  var pt=$('#biz-preview-tag');if(pt)pt.textContent=getBizHoursTag(o,c);
  var ph=$('#biz-preview-hrs');if(ph)ph.textContent=(c-o)+'小时';
  var pd=$('#biz-preview-days');
  if(pd){
    var days=(typeof G!=='undefined'&&G.state&&G.state.bizDays)?G.state.bizDays:PENDING_BIZ_DAYS;
    pd.textContent='营业日：'+getBizDaysLabel(days);
  }
}
function initDualSliderDrag(openVar,closeVar,isChanger){
  var slider=$('#dual-slider');if(!slider)return;
  var dragging=null;
  function pxToHour(px){
    var rect=slider.getBoundingClientRect();
    var pct=(px-rect.left)/rect.width;
    pct=Math.max(0,Math.min(1,pct));
    return Math.round(pct*24);
  }
  function startDrag(handle,which){
    return function(e){
      e.preventDefault();e.stopPropagation();
      dragging=which;
      if(typeof SFX!=='undefined')SFX.click();
      var move=function(ev){
        if(!dragging)return;
        ev.preventDefault();
        var px=ev.touches?ev.touches[0].clientX:ev.clientX;
        var h=pxToHour(px);
        if(dragging==='open'){
          if(h>=closeVar())h=closeVar()-1;
          openVar(h);
        }else{
          if(h<=openVar())h=openVar()+1;
          closeVar(h);
        }
        updateDualSliderUI(openVar(),closeVar());
      };
      var end=function(){dragging=null;document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',end);document.removeEventListener('touchmove',move);document.removeEventListener('touchend',end)};
      document.addEventListener('mousemove',move);document.addEventListener('mouseup',end);
      document.addEventListener('touchmove',move,{passive:false});document.addEventListener('touchend',end);
    };
  }
  var ho=$('#ds-handle-open');if(ho){ho.addEventListener('mousedown',startDrag(ho,'open'));ho.addEventListener('touchstart',startDrag(ho,'open'),{passive:false})}
  var hc=$('#ds-handle-close');if(hc){hc.addEventListener('mousedown',startDrag(hc,'close'));hc.addEventListener('touchstart',startDrag(hc,'close'),{passive:false})}
  // Also allow clicking on track to move nearest handle
  slider.addEventListener('mousedown',function(e){
    if(e.target!==slider&&!e.target.classList.contains('ds-track'))return;
    var h=pxToHour(e.clientX);
    var distO=Math.abs(h-openVar()),distC=Math.abs(h-closeVar());
    if(distO<=distC&&h<closeVar()){openVar(h)}else if(h>openVar()){closeVar(h)}
    updateDualSliderUI(openVar(),closeVar());
    if(typeof SFX!=='undefined')SFX.click();
  });
}
function toggleBizDay(day,isPending){
  var arr=isPending?PENDING_BIZ_DAYS:G.state.bizDays;
  var idx=arr.indexOf(day);
  if(idx>=0){arr.splice(idx,1)}
  else{arr.push(day)}
  if(isPending){
    var dp=$('#day-picker');if(dp){
      var btns=dp.querySelectorAll('.day-btn');
      btns.forEach(function(b,i){var d=i<6?i+1:0;b.classList.toggle('active',PENDING_BIZ_DAYS.indexOf(d)>=0)});
    }
    var pd=$('#biz-preview-days');if(pd)pd.textContent='营业日：'+getBizDaysLabel(PENDING_BIZ_DAYS);
  }else{G.markDirty();G.render()}
  if(typeof SFX!=='undefined')SFX.click();
}
