    currentTab:'shop',activeShopIdx:0,reviewFilter:'all',scoreFilter:'all',nextOrderId:1,
    homeTab:'takeout',tables:[],dineRecords:[],dineTodayCount:0,dineTodayIncome:0,
    dineFloors:1,dineCapacity:6,
    bizPlan:'24h',bizHoursId:_biz.id,bizOpenHour:_biz.openHour,bizCloseHour:_biz.closeHour,bizHoursLabel:_biz.hours,bizDays:(_biz.days||[1,2,3,4,5,6,0]).slice(),
    passiveTimer:0,orderTimer:0,eventActive:null,eventTimer:0,rawMaterialCost:0,supplyType:'prepped',
