  var exp=s.transactions.filter(function(t){return t.amount<0}).reduce(function(a,b){return a+b.amount},0);
  var inv=s.invoiceStats||{personal:0,company:0,noInvoice:0};
  var invTotal=inv.personal+inv.company+inv.noInvoice;
