    h+='<div class="inv-stub-row"><span class="inv-stub-label">\u91d1\u989d</span><span class="inv-stub-val">'+(t.amount>0?'+':'')+formatMoney(t.amount)+'\u5143</span></div>';
    if(t.cashier)h+='<div class="inv-stub-row"><span class="inv-stub-label">\u7ecf\u624b\u4eba</span><span class="inv-stub-val">'+t.cashier+'</span></div>';
    if(t.customer)h+='<div class="inv-stub-row"><span class="inv-stub-label">\u5ba2\u6237</span><span class="inv-stub-val">'+t.customer+'</span></div>';
    h+='</div>';
