  var statsStrip='<div style="display:flex;margin-top:12px;background:rgba(255,255,255,.22);border-radius:10px;padding:9px 0">'+
    '<div style="flex:1;text-align:center"><div style="font-size:17px;font-weight:800;line-height:22px">'+s.orders.length+'</div><div style="font-size:11px;opacity:.85;margin-top:2px">外卖进行中</div></div>'+
    '<div style="flex:1;text-align:center;border-left:1px solid rgba(255,255,255,.35)"><div style="font-size:17px;font-weight:800;line-height:22px">'+bOccupy+'</div><div style="font-size:11px;opacity:.85;margin-top:2px">堂食桌台</div></div>'+
    '<div style="flex:1;text-align:center;border-left:1px solid rgba(255,255,255,.35)"><div style="font-size:17px;font-weight:800;line-height:22px">+'+formatMoney(s.dailyIncome)+'</div><div style="font-size:11px;opacity:.85;margin-top:2px">今日营收</div></div>'+promoCell+supplyCell+'</div>';
  var dishImg=G.getDishImage(as.shopTypeId||as.type);
