  /* 厨房/餐厅明档隔断: 瓷砖墙裙+通透玻璃+主色顶梁, 传菜口为开放式明档窗 */
  FURN.kitchenPartition=function(){
    var g=new THREE.Group();
    var z=KZ, xL=-ROOM.w/2+.12, xR=ROOM.w/2-.12;
    var sillH=1.05, glassTop=2.46, th=.14;
    var tileTex=cvTex(128,128,function(x){
      x.fillStyle='#f3efe8';x.fillRect(0,0,128,128);
      x.strokeStyle='rgba(120,120,120,.3)';x.lineWidth=3;
      x.strokeRect(2,2,60,60);x.strokeRect(66,2,60,60);
      x.strokeRect(2,66,60,60);x.strokeRect(66,66,60,60);
    },8,1);
    var tileMat=new THREE.MeshStandardMaterial({map:tileTex,roughness:.92});
    var trimMat=M(TH.accent,.5,.3), frameMat=M(0x37474f,.6,.55);
    var glass=new THREE.MeshStandardMaterial({color:0xcfe6f2,roughness:.06,metalness:.25,transparent:true,opacity:.22});
    var steelMat=M(0xcfd6db,.4,.65);
    var passX0=-1.5, passX1=2.5;            /* 传菜口开口(对齐 pass 出餐台) */
    function seg(xa,xb,sill){
      var w=xb-xa, xc=(xa+xb)/2, h=glassTop-sill;
      g.add(box(w,sill,th,tileMat,xc,sill/2,z));               /* 瓷砖墙裙 */
      g.add(box(w,.07,th+.02,trimMat,xc,sill-.02,z));          /* accent 腰线 */
      g.add(box(w,h,th*.55,glass,xc,sill+h/2,z,false));        /* 通透玻璃 */
      g.add(box(w,.05,th+.02,frameMat,xc,sill,z,false));       /* 下框 */
      g.add(box(w,.05,th+.02,frameMat,xc,glassTop,z,false));   /* 上框 */
      g.add(box(.06,h,th+.02,frameMat,xa+.03,sill+h/2,z,false));/* 左立柱 */
      g.add(box(.06,h,th+.02,frameMat,xb-.03,sill+h/2,z,false));/* 右立柱 */
    }
    seg(xL,passX0,sillH);
    seg(passX1,xR,sillH);
    /* 传菜口: 开放式明档窗(无玻璃, 方便放/取餐) + 不锈钢窗台 + 立柱 + 顶框 */
    (function(){
      var xa=passX0,xb=passX1,w=xb-xa,xc=(xa+xb)/2,winSill=.95,h=glassTop-winSill;
      g.add(box(w,winSill,th,tileMat,xc,winSill/2,z));          /* 瓷砖墙裙 */
      g.add(box(w,.07,th+.02,trimMat,xc,winSill-.02,z));       /* accent 腰线 */
      g.add(box(w+.04,.06,th+.06,steelMat,xc,winSill,z,false));/* 不锈钢窗台 */
      g.add(box(.1,h,th+.04,frameMat,xa+.05,winSill+h/2,z,false));/* 左立柱 */
      g.add(box(.1,h,th+.04,frameMat,xb-.05,winSill+h/2,z,false));/* 右立柱 */
      g.add(box(w,.06,th+.04,frameMat,xc,glassTop,z,false));   /* 顶框 */
    })();
    g.add(box(xR-xL,th+.05,th+.07,trimMat,0,glassTop+th/2,z)); /* 顶梁 */
    return g;
  };
