G.rDineIn=function(){
  var s=this.state,h='';
  h+=G.segTabs();
  h+=G.statsBar();
  var occupy=s.tables.filter(function(t){return t.status!=='empty'}).length;
  var cap=s.dineCapacity||6,fl=s.dineFloors||1;
  h+='<div class="section-title">'+icon('users',18)+' 堂食大厅 '+
    '<span style="font-size:12px;color:var(--text-l);font-weight:400;flex:1">'+occupy+'/'+cap+'桌 · 第'+fl+'层 · 评分'+s.shopRating.toFixed(1)+
    ' · 今日'+s.dineTodayCount+'单 +'+formatMoney(s.dineTodayIncome)+'元</span>'+
    '<button class="menu-btn" onclick="G.openDineUpgrade()" style="padding:4px 12px">'+icon('trending-up',12)+' 扩建</button>'+
    '<button class="menu-btn" onclick="G.openShop3D(\'hall\')" style="padding:4px 12px">'+icon('eye',12)+' 店内监控</button></div>';
  h+='<div class="dine-grid'+(cap>12?' wide':'')+'">';
  s.tables.forEach(function(t){
    var extra,sc='';
    if(t.status==='empty'){
      sc=' dt-empty';extra='<div class="dt-empty-txt">'+icon('coffee',18)+'<span>空桌待客</span></div>';
    }else if(t.status==='cooking'){
      sc=' dt-busy';
      var names=(t.names||[]);
      extra='<div class="dt-items">'+names.slice(0,2).join('·')+(names.length>2?' 等'+names.length+'道':'')+'</div>'+
        '<div class="dt-prog"><div class="dt-fill" style="width:'+Math.min(100,Math.round(t.progress/t.need*100))+'%"></div></div>'+
        '<div class="dt-meta">'+icon('flame',11)+' 烹饪中 · ¥'+formatMoney(t.amount)+'</div>';
    }else{
      sc=' dt-eat';extra='<div class="dt-items">用餐中</div><div class="dt-meta">'+icon('utensils',11)+' ¥'+formatMoney(t.amount)+'</div>';
    }
    h+='<div class="dine-table'+sc+'"><div class="dt-top"><span class="dt-no">'+(t.id+1)+'号桌</span>'+
      (t.status==='empty'?'':'<span class="dt-seats">'+t.seats+'人</span>')+'</div>'+extra+'</div>';
  });
  h+='</div>';
  if(occupy>0)h+='<div class="help-tip">'+icon('users',14)+' 桌台满座后客人会自行等候，评分越高翻台越快</div>';
  h+='<div class="section-title">'+icon('clipboard-list',18)+' 堂食流水</div>';
  if(!s.dineRecords.length){
    h+='<div class="empty-state"><div class="e-icon">'+icon('users',36)+'</div><div>还没有堂食记录<br><span style="font-size:12px;color:var(--text-l)">评分越高，到店客人越多</span></div></div>';
  }else{
    h+='<div class="dine-list">';
    s.dineRecords.forEach(function(r){
      h+='<div class="dine-rec"><div class="dr-top"><span class="dr-tab">'+r.table+'号桌 · '+r.seats+'人</span>'+
        '<span class="dr-amt">+¥'+formatMoney(r.amount)+'</span></div>'+
        '<div class="dr-items">'+r.names+'</div>'+
        '<div class="dr-bot"><span class="dr-pay">'+icon('wallet',11)+' '+r.pay+'</span>'+
        (r.stars<=2?'<span class="dr-bad">'+icon('alert-triangle',11)+' '+r.text+'</span>':
          '<span class="dr-good">'+icon('star',11)+' '+(r.stars>=5?'五星':'四星')+' '+r.text+'</span>')+'</div></div>';
    });
    h+='</div>';
  }
  $('#p-shop').innerHTML=h;
};
